        return re.findall(r'\b[A-Z][a-z]+(?: [A-Z][a-z]+)*\b', text)

    def extract_date(text):
        # Date format: DD/MM/YYYY or DD/MM/YY
        return re.findall(r'\d{1,2}/\d{1,2}/\d{2,4}', text)

    def extract_location(text):
        # Location is typically a city and state or country
        return re.findall(r'\b[A-Za-z]+(?:, [A-Za-z]+)*\b', text)

    def extract_phone(text):
        # Phone number format: +1-XXX-XXX-XXXX or +1-XXX-XXX-XXXXxXXXX
        return re.findall(r'\+1-\d{3}-\d{3}-\d{4}(?:x\d{4})?', text)

    def extract_email(text):
        # Email format: local-part@domain
        return re.findall(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', text)

